INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('6ce733bc-4389-497d-8c85-9b4ef252f91d', 'Pizzeria Tivoli', 'Włoska', 'Najstarsza pizzeria w Poznaniu - działa od 1991 roku. Pizza pieczona w piecu opalanym drewnem grabowym, makarony, zapiekanki i dania z grilla z naturalnych składników sprowadzanych z Włoch. Sieć 5 lokali w mieście, dowóz i odbiór na miejscu.', '4.5', 'ul. Świętego Czesława 3, 61-582 Poznań', '52.396', '16.925', '', '', '0', '2026-07-27 13:08:24.058175+00', '2026-07-27 13:08:24.058175+00', '', '', 'pizzeria-tivoli', '', 'false', '61 833 62 52', 'https://www.pizzeriativoli.pl/', '', 'false', 'false', 'Wilda', '{"fri": {"open": "12:00", "close": "23:00"}, "mon": {"open": "12:00", "close": "22:00"}, "sat": {"open": "12:00", "close": "23:00"}, "sun": {"open": "12:00", "close": "22:00"}, "thu": {"open": "12:00", "close": "22:00"}, "tue": {"open": "12:00", "close": "22:00"}, "wed": {"open": "12:00", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
