INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('2cdb240d-c19e-45f8-b696-4e7194a9514f', 'The Time Grill & Wine', 'Mix', 'Grill & wine fine dining w zabytkowej kamienicy Młyńska12. Dania główne przygotowywane w piecu MIBRASA opalanym węglem drzewnym - ryby zapiekane w soli, soczyste mięsa. Szef kuchni Dawid Łagowski, starannie dobrany wine pairing. Rekomendacja Przewodnika Michelin 2023-2025.', '4.5', 'ul. Młyńska 12, 61-730 Poznań', '52.410822', '16.925882', '', '', '0', '2026-07-27 15:19:13.717441+00', '2026-07-27 15:19:13.717441+00', '', '', 'the-time-grill-wine', '', 'false', '+48 606 431 689', 'https://mlynska12.pl/restauracja-the-time/', '$$$$$', 'false', 'false', 'Stare Miasto', '{"fri": {"open": "17:00", "close": "23:59"}, "sat": {"open": "14:00", "close": "23:59"}, "sun": {"open": "14:00", "close": "18:00"}, "thu": {"open": "17:00", "close": "23:00"}, "tue": {"open": "17:00", "close": "23:00"}, "wed": {"open": "17:00", "close": "23:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
