INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('b78393e2-429f-4d3b-aa34-0f845cb1642c', 'Togosho Sushi & Asian Food', 'Sushi', 'Togosho Sushi & Asian Food łączy japońskie sushi z kuchnią azjatycką na Bukowskiej. W karcie klasyczne rolki, zestawy oraz autorskie sushi burgery. Szefowie kuchni z ponad 15-letnim doświadczeniem, codzienne promocje na wynos.', '4.5', 'ul. Bukowska 15, 60-809 Poznań', '52.406879', '16.908681', '', '', '0', '2026-07-27 01:20:25.345724+00', '2026-07-27 11:12:33.818876+00', '', '', 'togosho-sushi-asian-food', '', 'false', '+48 888 817 748', 'https://togosho-sushi.pl/', '$$$', 'false', 'false', 'Grunwald', '{"fri": {"open": "12:00", "close": "23:00"}, "mon": {"open": "12:00", "close": "23:00"}, "sat": {"open": "12:00", "close": "23:00"}, "sun": {"open": "12:00", "close": "23:00"}, "thu": {"open": "12:00", "close": "23:00"}, "tue": {"open": "12:00", "close": "23:00"}, "wed": {"open": "12:00", "close": "23:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('4403f267-a32e-46e0-99fb-70083fb865e5', '3 Kolory Malta', 'Polska', 'Restauracja z widokiem na Jezioro Maltańskie, słynąca z kaczki po poznańsku uznawanej za jedną z najlepszych w mieście od 2017 roku. W karcie kuchnia europejska z autorskimi daniami, grillowanie na kamieniach z lawy wulkanicznej (Grill Stone) i piękny taras nad wodą. Idealne miejsce na obiad, kolację we dwóje lub imprezę okolicznościową.', '4.5', 'ul. Wiankowa 3, 61-131 Poznań', '52.400145', '16.984907', '', '', '0', '2026-07-27 11:44:45.591438+00', '2026-07-27 11:44:45.591438+00', '', '', '3-kolory-malta', '', 'false', '+48 501 402 827', 'https://3-kolory.pl/malta/', '$$$$', 'false', 'false', 'Chartowo', '{"fri": {"open": "12:00", "close": "22:00"}, "mon": {"open": "11:00", "close": "15:00"}, "sat": {"open": "12:00", "close": "22:00"}, "sun": {"open": "12:00", "close": "20:00"}, "thu": {"open": "12:00", "close": "21:00"}, "tue": {"open": "12:00", "close": "21:00"}, "wed": {"open": "12:00", "close": "21:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('985c4bd9-d9a6-4772-b54d-da611a93f3a5', 'Tendur Kebab', 'Kebaby', 'Kraftowy kebab z lawaszem pieczonym na miejscu w piecu tandoor. Część sieci znanej z Warszawy, Częstochowy i Lublina - poznański lokal przy Półwiejskiej, tuż obok Starego Browaru. Mięso najwyższej jakości, autorskie sosy.', '4.5', 'ul. Półwiejska 33, 61-886 Poznań', '52.4074', '16.9256', '', '', '0', '2026-07-27 12:19:24.492972+00', '2026-07-27 12:19:24.492972+00', '', '', 'tendur-kebab', '', 'false', '', 'https://tendurkebap.pl/', '', 'false', 'false', 'Stare Miasto', NULL, NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('5b996ac1-663b-4d57-9f84-cde76b7ff7bd', 'Restauracja Garaż', 'Włoska', 'Rodzinna włoska restauracja z ponad 18-letnią tradycją, mieszcząca się w kompleksie Kinepolis. Pizza, makarony, sałatki i lekkie lunche, a także słodkości - naleśniki, ciasta, desery. Świetny wybór na obiad przed lub po seansie kinowym, również na imprezy okolicznościowe i catering.', '4.5', 'ul. Bolesława Krzywoustego 72, 61-144 Poznań', '52.374512', '16.980136', '', '', '0', '2026-07-27 12:43:24.619838+00', '2026-07-27 12:43:24.619838+00', '', '', 'restauracja-garaz', '', 'false', '+48 61 877 56 68', 'https://restauracjagaraz.pl/', '', 'false', 'false', 'Rataje', '{"fri": {"open": "15:00", "close": "21:00"}, "mon": {"open": "16:00", "close": "21:00"}, "sat": {"open": "12:00", "close": "22:00"}, "sun": {"open": "12:00", "close": "20:00"}, "thu": {"open": "15:00", "close": "21:00"}, "tue": {"open": "16:00", "close": "21:00"}, "wed": {"open": "15:00", "close": "21:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('4aff7ee3-ca39-4ade-a67b-27c16bfe1305', 'Maremma', 'Włoska', 'Autorska kuchnia włoska inspirowana toskańsko-lazyjską Maremmą - jakościowe steki z szafy dojrzewalniczej, świeże makarony, ryby i owoce morza. Wyróżnienie w przewodniku Michelin (Sommelier Award 2026) i tytuł White Star za kartę win. Eleganckie, kameralne wnętrze idealne na kolację we dwóje lub spotkanie biznesowe.', '4.5', 'ul. ks. Jakuba Wujka 9, 61-581 Poznań', '52.3985', '16.9075', '', '', '0', '2026-07-27 12:49:24.422304+00', '2026-07-27 12:49:24.422304+00', '', '', 'maremma', '', 'false', '+48 789 809 070', 'https://maremma.pl/', '', 'false', 'false', 'Wilda', '{"fri": {"open": "16:00", "close": "23:00"}, "sat": {"open": "16:00", "close": "23:00"}, "thu": {"open": "17:00", "close": "22:00"}, "tue": {"open": "17:00", "close": "22:00"}, "wed": {"open": "17:00", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('dffc3e94-baa0-479c-bddf-dfdfc985cc0d', 'DRAM: Cocktail Bar & Restaurant', 'Mix', 'Cocktail bar i restauracja na Starym Rynku - autorskie koktajle i kuchnia, codziennie muzyka na żywo. Klimatyczne miejsce w samym sercu Poznania, idealne na wieczór z drinkiem lub kolację przy dobrej muzyce.', '4.5', 'Stary Rynek 92, Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 13:14:04.437208+00', '2026-07-27 13:14:04.437208+00', '', '', 'dram-cocktail-bar-restaurant', '', 'false', '', '', '$$$$', 'false', 'false', 'Stare Miasto', NULL, NULL, 'false', '') ON CONFLICT DO NOTHING;
