INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('57299f3a-e6a2-4514-a67a-121a49c05a4f', 'Wypas', 'Wegańska', 'Jedna z pierwszych wegańskich restauracji w Poznaniu - autorskie, sezonowe dania inspirowane kuchnią azjatycką, śródziemnomorską i europejską. Curry, kremowe zupy, domowe pasty i roślinne burgery, wiele opcji bezglutenowych. Kameralne wnętrze z otwartą kuchnią, latem mały ogródek.', '4.5', 'ul. Jackowskiego 38/1, 60-512 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 17:27:25.156801+00', '2026-07-27 17:27:25.156801+00', '', '', 'wypas', '', 'false', '+48 61 226 46 00', 'https://wypas.co/', '$$', 'false', 'false', 'Jeżyce', '{"fri": {"open": "12:30", "close": "21:00"}, "mon": {"open": "12:30", "close": "19:00"}, "sat": {"open": "12:30", "close": "21:00"}, "sun": {"open": "12:30", "close": "19:00"}, "thu": {"open": "12:30", "close": "21:00"}, "wed": {"open": "12:30", "close": "19:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
