INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('517547ba-df7f-452e-a1a6-657b4c20095e', 'K-BOB', 'Azjatycka', 'Koreański street food od ekipy Fat Bob Family (Balans, Ichiban Ramen Shop). Korean Fried Chicken w autorskiej panierce, corndogi, smażone lody. Nowoczesny wystrój - beton i azjatycki minimalizm. Walk-in only, bez rezerwacji.', '4.5', 'ul. Żydowska 26, Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 17:57:25.204109+00', '2026-07-27 17:57:25.204109+00', '', '', 'k-bob', '', 'false', '+48 730 022 227', '', '$$', 'false', 'false', 'Stare Miasto', '{"fri": {"open": "12:00", "close": "23:00"}, "mon": {"open": "12:00", "close": "22:00"}, "sat": {"open": "12:00", "close": "23:00"}, "sun": {"open": "12:00", "close": "22:00"}, "thu": {"open": "12:00", "close": "22:00"}, "tue": {"open": "12:00", "close": "22:00"}, "wed": {"open": "12:00", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('e9b25ce1-3742-4e8c-98af-9a0ad73ff2d3', 'Restauracja Panorama (Hotel HP Park)', 'Polska', 'Restauracja hotelu HP Park z widokiem na Jezioro Maltańskie. Domowa kuchnia polska i europejska od szefa Dominika Brodziaka - kaczka po poznańsku, pierogi, chleb pieczony na miejscu. Letni taras nad jeziorem, idealne na rodzinny obiad lub imprezę okolicznościową. UWAGA: godziny otwarcia niepotwierdzone - zweryfikuj przed publikacją.', '4.5', 'ul. abpa A. Baraniaka 77, 61-131 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 18:23:13.704543+00', '2026-07-27 18:23:13.704543+00', '', '', 'restauracja-panorama-hotel-hp-park', '', 'false', '+48 61 874 11 00', 'https://hotelepark.pl/poznan/kulinaria/restauracja', '', 'false', 'false', 'Chartowo', '{"fri": {"open": "12:00", "close": "22:00"}, "mon": {"open": "12:00", "close": "22:00"}, "sat": {"open": "12:00", "close": "22:00"}, "sun": {"open": "12:00", "close": "22:00"}, "thu": {"open": "12:00", "close": "22:00"}, "tue": {"open": "12:00", "close": "22:00"}, "wed": {"open": "12:00", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
