INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('f2564ea0-00f2-4f39-8e69-03c6ab899876', 'DeliCafé', 'Mix', 'Francuska winiarnia i delikatesy w sercu Szczepankowa - francuskie sery, wędliny i ponad 150 marek win. W tygodniu polskie obiady w świetnej cenie, w weekendy pełne menu à la carte i francuskie tapas przy winie. Kolacje degustacyjne "Francja na talerzu", muzyka na żywo.', '4.5', 'ul. Szczepankowo 92/1, 61-306 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 21:51:27.963226+00', '2026-07-27 21:51:27.963226+00', '', '', 'delicaf', '', 'false', '', 'https://delicafe.pl/', '', 'false', 'false', 'Szczepankowo', '{"fri": {"open": "12:00", "close": "22:00"}, "mon": {"open": "12:00", "close": "19:00"}, "sat": {"open": "12:00", "close": "22:00"}, "sun": {"open": "12:00", "close": "19:00"}, "thu": {"open": "12:00", "close": "19:00"}, "tue": {"open": "12:00", "close": "19:00"}, "wed": {"open": "12:00", "close": "19:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('50eda653-687b-44f9-a986-5641efab136d', 'Dragon Hill', 'Burgery', 'Burgerownia z motywem smoków z różnych kultur (skandynawskiej, andyjskiej, greckiej) - każdy burger nazwany i inspirowany innym mitycznym smokiem. Burgery mięsne i wegetariańskie, tortille, kraftowy kebab, smocze mocktaile. Dwa lokale: Poznań (Jeżyce) i Gniezno.', '4.5', 'ul. Adama Mickiewicza 20, 60-834 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 21:55:25.321871+00', '2026-07-27 21:55:25.321871+00', '', '', 'dragon-hill', '', 'false', '+48 600 498 627', 'https://dragonhill.pl/', '', 'false', 'false', 'Jeżyce', '{"fri": {"open": "12:00", "close": "23:30"}, "mon": {"open": "12:00", "close": "23:30"}, "sat": {"open": "12:00", "close": "23:30"}, "sun": {"open": "12:00", "close": "23:30"}, "thu": {"open": "12:00", "close": "23:30"}, "tue": {"open": "12:00", "close": "23:30"}, "wed": {"open": "12:00", "close": "23:30"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('0553d453-b395-4d44-850c-9b6cf656c01e', 'Shawarma from Odessa', 'Kebaby', 'Autentyczna odeska shawarma - sekretna receptura sosów i marynata do mięsa, jedyna taka w Polsce. Mięso z grilla, świeże warzywa, lawasz. UWAGA: godziny otwarcia niepotwierdzone - zweryfikuj przed publikacją.', '4.5', 'ul. Św. Rocha 8, 61-142 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 22:02:25.478934+00', '2026-07-27 22:02:25.478934+00', '', '', 'shawarma-from-odessa', '', 'false', '+48 536 934 999', '', '', 'false', 'false', 'Stare Miasto', '{"fri": {"open": "12:00", "close": "22:00"}, "mon": {"open": "12:00", "close": "22:00"}, "sat": {"open": "12:00", "close": "22:00"}, "sun": {"open": "12:00", "close": "22:00"}, "thu": {"open": "12:00", "close": "22:00"}, "tue": {"open": "12:00", "close": "22:00"}, "wed": {"open": "12:00", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('feeec0d7-1e28-4139-8e7a-70c4976f325f', 'JEMRAMEN&chicken', 'Ramen', 'Japoński ramen i koreański chrupiący fried chicken w klimacie azjatyckiego street foodu - kilka rodzajów bulionu (klasyczne, pikantne, wege), gyoza, edamame, kimchi, autorskie koktajle. Otwarte w miejscu dawnego Zdolni 2.0. UWAGA: godziny otwarcia niepotwierdzone - zweryfikuj przed publikacją.', '4.5', 'ul. Kościelna 48, Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 22:32:20.405663+00', '2026-07-27 22:32:20.405663+00', '', '', 'jemramen-chicken', '', 'false', '+48 604 431 700', '', '', 'false', 'false', 'Jeżyce', '{"fri": {"open": "12:00", "close": "21:00"}, "mon": {"open": "12:00", "close": "21:00"}, "sat": {"open": "12:00", "close": "21:00"}, "sun": {"open": "12:00", "close": "21:00"}, "thu": {"open": "12:00", "close": "21:00"}, "tue": {"open": "12:00", "close": "21:00"}, "wed": {"open": "12:00", "close": "21:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
