INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('6d738cde-18f8-4c67-8fcf-b5be5c3f762a', 'Przyjemność', 'Włoska', 'Pizza i szprycer w kultowej, mocno zaprojektowanej przestrzeni na Wildzie (od 2018 r.) - włoski street food i domowa kuchnia włoska serwowane przy wspólnym granitowym stole. Inspirowane włoską gościnnością i kulturą street foodu, neonowe szyldy i charakterystyczny design wnętrza.', '4.5', 'ul. Górna Wilda 82/84, 61-564 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 23:11:25.35311+00', '2026-07-27 23:11:25.35311+00', '', '', 'przyjemnosc', '', 'false', '+48 789 385 455', 'https://www.przyjemnoscpizza.pl/', '', 'false', 'false', 'Wilda', '{"fri": {"open": "13:00", "close": "22:00"}, "mon": {"open": "13:00", "close": "22:00"}, "sat": {"open": "13:00", "close": "22:00"}, "sun": {"open": "13:00", "close": "22:00"}, "thu": {"open": "13:00", "close": "22:00"}, "tue": {"open": "13:00", "close": "22:00"}, "wed": {"open": "13:00", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('94df8303-2fe4-44e0-bfbd-ab5f28181931', 'Turecka-Szama', 'Kebaby', 'Niepozorna, kameralna budka kebabowa - lawasz pieczony na miejscu, mięso robione raz dziennie (świeżo), darmowa aromatyczna herbata dla gości. Znana z jakości składników i miłej obsługi. Godziny zamknięcia bywają ruchome w zależności od zapasu mięsa.', '4.5', 'ul. Głogowska 99A, 60-738 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 23:18:25.470387+00', '2026-07-27 23:18:25.470387+00', '', '', 'turecka-szama', '', 'false', '+48 881 557 553', '', '', 'false', 'false', 'Grunwald', '{"fri": {"open": "11:00", "close": "22:00"}, "sat": {"open": "11:00", "close": "22:00"}, "sun": {"open": "11:00", "close": "21:00"}, "thu": {"open": "11:00", "close": "21:00"}, "tue": {"open": "11:00", "close": "21:00"}, "wed": {"open": "11:00", "close": "21:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('d1cd83c8-f708-4d4d-8a98-fce13bb7e641', 'Turkish Kebab (Halal)', 'Kebaby', 'Tradycyjny turecki kebab halal w sercu Poznania, przy pomniku Adama Mickiewicza. Różne rodzaje pieczywa (bułka, tortilla, lawasz), wołowina i jagnięcina, opcje wegetariańskie (falafel). Kraftowe mięso, tylko na wynos (brak miejsc siedzących).', '4.5', 'ul. Święty Marcin 45, 61-714 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 23:22:43.1744+00', '2026-07-27 23:22:43.1744+00', '', '', 'turkish-kebab-halal', '', 'false', '+48 575 064 741', '', '', 'false', 'false', 'Stare Miasto', '{"fri": {"open": "11:00", "close": "19:00"}, "sat": {"open": "11:00", "close": "19:00"}, "sun": {"open": "11:00", "close": "19:00"}, "thu": {"open": "11:00", "close": "19:00"}, "tue": {"open": "11:00", "close": "19:00"}, "wed": {"open": "11:00", "close": "19:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('5bf50d17-e85d-4f11-b034-d4aebf1ee809', 'U Marudy', 'Polska', 'Bar mleczny w stylu "wchodzisz, wybierasz, nakładają, płacisz" - domowe polskie obiady (schabowy, barszcz ukraiński, kaczka) w bardzo przystępnych cenach. Duże porcje, szybka obsługa. UWAGA: godziny otwarcia niepotwierdzone - zweryfikuj przed publikacją.', '4.5', 'ul. Zamenhofa 133 (Pasaż Rondo, I piętro), 61-131 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 23:25:26.472436+00', '2026-07-27 23:25:26.472436+00', '', '', 'u-marudy', '', 'false', '+48 507 368 750', '', '', 'false', 'false', 'Rataje', '{"fri": {"open": "10:00", "close": "18:00"}, "mon": {"open": "10:00", "close": "18:00"}, "thu": {"open": "10:00", "close": "18:00"}, "tue": {"open": "10:00", "close": "18:00"}, "wed": {"open": "10:00", "close": "18:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('4edabfad-a878-4d96-9139-68d650b6d41a', 'Pianta Pizza e Pasta', 'Włoska', 'Włoska restauracja w budynku Teatru Nowego (poziom -1) na Jeżycach - pizza neapolitańska z pieca opalanego drewnem, włoskie makarony i desery, cocktail bar. Wegetariańskie i weganskie opcje, selekcja win. Otwarte od 2023 roku.', '4.5', 'ul. Jana Henryka Dąbrowskiego 5, 60-838 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-27 23:56:26.500948+00', '2026-07-27 23:56:26.500948+00', '', '', 'pianta-pizza-e-pasta', '', 'false', '+48 500 705 105', '', '', 'false', 'false', 'Jeżyce', '{"fri": {"open": "12:00", "close": "23:59"}, "mon": {"open": "12:00", "close": "23:00"}, "sat": {"open": "12:00", "close": "23:59"}, "sun": {"open": "12:00", "close": "23:00"}, "thu": {"open": "12:00", "close": "23:00"}, "tue": {"open": "12:00", "close": "23:00"}, "wed": {"open": "12:00", "close": "23:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('fedbc967-99e4-4bef-8213-5475b3973614', 'Pansa Piena', 'Włoska', 'Kultowa budka street food rozmiaru XS na Placu Wielkopolskim (pawilon nr 8) - autentyczna włoska pizza na cienkim cieście i doskonała kawa od włoskiego szefa Angelo. Tylko gotówka, ceny bardzo przystępne.', '4.5', 'pawilon nr 8, plac Wielkopolski, 60-101 Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-28 00:31:26.175506+00', '2026-07-28 00:31:26.175506+00', '', '', 'pansa-piena', '', 'false', '+48 665 916 156', '', '', 'false', 'false', 'Stare Miasto', '{"fri": {"open": "08:30", "close": "23:00"}, "mon": {"open": "08:30", "close": "22:00"}, "sat": {"open": "10:00", "close": "23:00"}, "sun": {"open": "10:00", "close": "23:00"}, "thu": {"open": "08:30", "close": "23:00"}, "tue": {"open": "08:30", "close": "22:00"}, "wed": {"open": "08:30", "close": "22:00"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
INSERT INTO public."places" ("id", "name", "cuisine", "description", "rating", "address", "lat", "lng", "reel_url", "cover_image_url", "sort_order", "created_at", "updated_at", "menu_url", "menu_image_url", "slug", "promo_label", "promo_active", "phone", "website", "price_range", "has_takeaway", "wheelchair_accessible", "district", "opening_hours", "menu_items", "is_published", "avatar_url") VALUES ('cca86e75-3815-4f28-92a8-28bfd3df62eb', 'Winogratka', 'Włoska', 'Kameralna pizzeria na Winogradach, niedaleko Cytadeli - pizza na cienkim cieście dojrzewającym 72 godziny, chrupiące brzegi, oryginalne dodatki (np. Marinara Burrata z zestem cytrynowym). Letni ogródek, pizza + wino lub piwo w duecie.', '4.5', 'ul. Przełajowa 14, Poznań', '52.4082', '16.9335', '', '', '0', '2026-07-28 15:15:13.427412+00', '2026-07-28 15:15:13.427412+00', '', '', 'winogratka', '', 'false', '+48 733 833 413', 'https://www.winogratka.pl/', '', 'false', 'false', 'Winogrady', '{"fri": {"open": "12:30", "close": "21:30"}, "mon": {"open": "12:30", "close": "21:30"}, "sat": {"open": "13:00", "close": "21:30"}, "sun": {"open": "13:00", "close": "21:30"}, "thu": {"open": "12:30", "close": "21:30"}, "tue": {"open": "12:30", "close": "21:30"}, "wed": {"open": "12:30", "close": "21:30"}}', NULL, 'false', '') ON CONFLICT DO NOTHING;
